from math import exp

from decomposition import mean, total


KINDS = ("none", "first", "seasonal", "both")


def difference(values, season, kind):
    if kind == "none":
        return list(values), 0
    if kind == "first":
        return [values[t] - values[t - 1] for t in range(1, len(values))], 1
    if kind == "seasonal":
        return [values[t] - values[t - season] for t in range(season, len(values))], season
    return ([(values[t] - values[t - 1]) - (values[t - season] - values[t - season - 1])
             for t in range(season + 1, len(values))], season + 1)


def autocorrelation(values, max_lag):
    average = mean(values)
    centered = [value - average for value in values]
    count = len(values)
    variance = total(value * value for value in centered) / count
    correlations = [1.0]
    for lag in range(1, max_lag + 1):
        numerator = total(centered[i] * centered[i + lag] for i in range(count - lag))
        correlations.append(numerator / count / variance)
    return average, variance, correlations


def durbin_levinson(correlations):
    coefficients = [[]]
    partial = [0.0]
    variances = [1.0]
    for order in range(1, len(correlations)):
        previous = coefficients[-1]
        correction = total(previous[j - 1] * correlations[order - j] for j in range(1, order))
        theta = (correlations[order] - correction) / variances[-1]
        current = [previous[j - 1] - theta * previous[order - j - 1]
                   for j in range(1, order)] + [theta]
        coefficients.append(current)
        partial.append(theta)
        variances.append(variances[-1] * (1 - theta * theta))
    return coefficients, partial, variances


def residuals(values, average, coefficients):
    order = len(coefficients)
    return [values[i] - average - total(coefficients[j - 1] * (values[i - j] - average)
                                        for j in range(1, order + 1))
            for i in range(order, len(values))]


def forecast(values, differenced, offset, kind, average, coefficients, origin, steps, season):
    transformed = list(differenced[:origin - offset])
    extended = list(values[:origin])
    result = []
    for _ in range(steps):
        predicted = average + total(coefficient * (transformed[-j] - average)
                                    for j, coefficient in enumerate(coefficients, 1))
        transformed.append(predicted)
        if kind == "first":
            predicted += extended[-1]
        elif kind == "seasonal":
            predicted += extended[-season]
        elif kind == "both":
            predicted = predicted + extended[-1] + extended[-season] - extended[-season - 1]
        extended.append(predicted)
        result.append(predicted)
    return result


def ljung_box(errors, lags):
    count = len(errors)
    _, _, correlations = autocorrelation(errors, max(lags))
    result = []
    for lag in lags:
        q = count * (count + 2) * total(correlations[k] * correlations[k] / (count - k)
                                      for k in range(1, lag + 1))
        x = q / 2
        term = 1.0
        terms = [term]
        for i in range(1, lag // 2):
            term = term * x / i
            terms.append(term)
        result.append((lag, q, exp(-x) * total(terms)))
    return result

def total(values):
    result = 0.0
    for value in values:
        result += value
    return result


def mean(values):
    return total(values) / len(values)


def sample_variance(values):
    average = mean(values)
    return total((value - average) * (value - average) for value in values) / (len(values) - 1)


def decompose(values, season):
    count = len(values)
    half = season // 2
    defined = list(range(half, count - half))
    trend = [None] * count
    for t in defined:
        value = 0.5 * values[t - half]
        for i in range(t - half + 1, t + half):
            value += values[i]
        value += 0.5 * values[t + half]
        trend[t] = value / season
    additive = []
    multiplicative = []
    for position in range(season):
        times = [t for t in defined if t % season == position]
        additive.append(mean([values[t] - trend[t] for t in times]))
        multiplicative.append(mean([values[t] / trend[t] for t in times]))
    average_add = total(additive) / season
    average_mult = total(multiplicative) / season
    additive = [value - average_add for value in additive]
    multiplicative = [value / average_mult for value in multiplicative]
    residual_add = [None] * count
    residual_mult = [None] * count
    for t in defined:
        residual_add[t] = values[t] - trend[t] - additive[t % season]
        residual_mult[t] = values[t] / (trend[t] * multiplicative[t % season])
    return {"trend": trend, "additive": additive, "multiplicative": multiplicative,
            "residual_add": residual_add, "residual_mult": residual_mult, "defined": defined}


def least_squares_line(values):
    count = len(values)
    center = (count + 1) / 2
    average = mean(values)
    numerator = total((t + 1 - center) * (value - average) for t, value in enumerate(values))
    denominator = total((t + 1 - center) * (t + 1 - center) for t in range(count))
    slope = numerator / denominator
    return average - slope * center, slope

from math import sqrt

from decomposition import total


def seasonal_scale(values, season):
    return total(abs(values[t] - values[t - season])
                 for t in range(season, len(values))) / (len(values) - season)


def accuracy(actual, predicted, scale):
    count = len(actual)
    errors = [observed - forecast for observed, forecast in zip(actual, predicted)]
    mae = total(abs(value) for value in errors) / count
    return {
        "me": total(errors) / count, "mae": mae,
        "rmse": sqrt(total(value * value for value in errors) / count),
        "mape": 100 * total(abs(error) / value for error, value in zip(errors, actual)) / count,
        "smape": 100 * total(2 * abs(error) / (abs(a) + abs(f))
                             for error, a, f in zip(errors, actual, predicted)) / count,
        "mase": mae / scale,
    }


def winkler(actual, low, high, multiplier):
    if actual < low:
        return high - low + multiplier * (low - actual)
    if actual > high:
        return high - low + multiplier * (actual - high)
    return high - low


def rank_models(ordered_names, metrics):
    return sorted(ordered_names, key=lambda name: (metrics[name]["rmse"], ordered_names.index(name)))

import csv
from pathlib import Path


def rows(name):
    with open(Path("input") / name, encoding="ascii", newline="") as handle:
        return list(csv.DictReader(handle))


def read_inputs():
    series = {}
    for row in rows("series.csv"):
        record = series.setdefault(row["series"], {"periods": [], "raw": []})
        record["periods"].append(row["period"])
        record["raw"].append(None if row["value"] == "NA" else int(row["value"]))
    events = {name: {} for name in series}
    for row in rows("events.csv"):
        events[row["series"]][row["period"]] = row["kind"]
    inventory = {}
    for row in rows("inventory.csv"):
        inventory[row["series"]] = {
            "on_hand": int(row["on_hand"]), "lead_time": int(row["lead_time"]),
            "review": int(row["review"]), "service": float(row["service"]),
        }
    settings = {}
    for line in Path("input/params.txt").read_text(encoding="ascii").splitlines():
        key, *values = line.split(" ")
        if key in ("alpha", "beta", "gamma", "phi", "interval"):
            settings[key] = list(map(float, values))
        elif key == "ljung_box":
            settings[key] = list(map(int, values))
        elif key == "outlier":
            settings[key] = float(values[0])
        else:
            settings[key] = int(values[0])
    return series, events, inventory, settings


def next_month(period):
    year, month = map(int, period.split("-"))
    year += month // 12
    month = month % 12 + 1
    return f"{year:04d}-{month:02d}"


def real(value):
    if value is None:
        return "NA"
    result = f"{value:.4f}"
    return "0.0000" if result == "-0.0000" else result


def write_lines(name, lines):
    target = Path("output") / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(lines) + "\n", encoding="ascii")
